private TreeNode<T> rotateRight(TreeNode<T> node) {
    // Check if the node has a left child
    if (node.left == null) {
        return node;
    }

    // Save the left child
    TreeNode<T> left = node.left;

    // the new parent of the node
    TreeNode<T> newParent = left;

    // set the left child of the new parent
    newParent.left = node;

    // set the parent of the node to the new parent
    node.parent = newParent;

    // set the left child of the node to null
    node.left = null;

    return newParent;
}

public TreeNode<T> rotateRight(TreeNode<T> node) {
    // Check if the node is null
    if (node == null) {
        throw new NullPointerException("Cannot rotate a null node");
    }

    // Get the left child of the node
    TreeNode<T> leftChild = node.getLeft();

    // Check if the left child is null
    if (leftChild == null) {
        throw new NullPointerException("Cannot rotate a node with a null left child");
    }

    // Get the right child of the left child
    TreeNode<T> leftChildRightChild = leftChild.getRight();

    // Check if the right child of the left child is null
    if (leftChildRightChild == null) {
        // If the right child is null, it means that the left child is the new root
        // Set the left child as the new root and return it
        return leftChild;
    }

    // Get the left child's left child
    TreeNode<T> leftChildLeftChild = leftChild.getLeft();

    // Set the left child's left child as the new root
    leftChild.setLeft(leftChildLeftChild);

    // Set the right child of the left child as the left child of the node
    leftChild.setRight(node);

    // Set the left child as the right child of the node
    node.setRight(leftChild);

    // Return the new parent of the node
    return node;
}

public TreeNode<T> rotateRight(TreeNode<T> node) {
    // Check if node is not null
    if (node == null) {
        throw new IllegalArgumentException("Cannot rotate a null node.");
    }

    // Get the left child of the node
    TreeNode<T> leftChild = node.getLeft();

    // If the left child is null, return the node
    if (leftChild == null) {
        return node;
    }

    // Get the right child of the left child
    TreeNode<T> rightChild = leftChild.getRight();

    // If the right child is null, set the right child of the node to the left child and return the node
    if (rightChild == null) {
        node.setRight(leftChild);
        return node;
    }

    // Set the parent of the left child to the right child
    leftChild.setParent(rightChild);

    // Set the right child of the node to the left child
    node.setLeft(rightChild);

    // Set the parent of the right child to the node
    rightChild.setParent(node);

    return node;
}

