public int parseEndOfLine(String headerPart, int end) {
    // Step 1: Find the next \r\n sequence
    int index = headerPart.indexOf("\r\n", end);

    // Step 2: If \r\n sequence is not found, throw an exception
    if (index < 0) {
        throw new IllegalArgumentException("Invalid headers: Missing end of line sequence");
    }

    // Step 3: Return the index of the \r\n sequence
    return index;
}

private int parseEndOfLine(String headerPart, int end) {
    // Search for the \r\n sequence that marks the end of the line
    int indexOfCR = headerPart.indexOf("\r", end);
    int indexOfLF = headerPart.indexOf("\n", end);
    if (indexOfCR == -1 && indexOfLF == -1) {
        // If no \r\n sequence is found, the header is malformed
        throw new IllegalArgumentException("Malformed header: no end of line found");
    }
    else if (indexOfCR != -1 && indexOfLF != -1) {
        // If both \r and \n are found, use the one that comes first
        return Math.min(indexOfCR, indexOfLF);
    }
    else {
        // If only one of \r or \n is found, use it
        return indexOfCR != -1 ? indexOfCR : indexOfLF;
    }
}

else if (indexOfCR != -1 && indexOfLF != -1) {
        // If both \r and \n are found, use the one that comes first
        return Math.min(indexOfCR, indexOfLF);
    }

private int parseEndOfLine(String headerPart, int end) {
    for (int i = end; i < headerPart.length(); i++) {
        if (headerPart.charAt(i) == '\r' && headerPart.charAt(i + 1) == '\n') {
            return i + 1;
        }
    }
    return -1;
}

private int parseEndOfLine(String headerPart, int end) {
    // Initialize variable to store the index of the \r\n sequence
    int eolIndex = -1;

    // Iterate through the bytes until the end of the line is found
    for (int i = end; i < headerPart.length(); i++) {
        // If the current byte is a carriage return, check if the previous byte is a line feed
        if (headerPart.charAt(i) == '\r') {
            if (headerPart.charAt(i - 1) == '\n') {
                // If the previous byte is a line feed, then the current byte is the first byte of the \r\n sequence
                eolIndex = i;
                break;
            }
        }
        // If the current byte is a line feed, then the current byte is the first byte of the \r\n sequence
        else if (headerPart.charAt(i) == '\n') {
            eolIndex = i;
            break;
        }
    }

    // Return the index of the \r\n sequence, or -1 if it was not found
    return eolIndex;
}

else if (headerPart.charAt(i) == '\n') {
            eolIndex = i;
            break;
        }

