public void generateGraph(Graph<V,E> target,Map<String,V> resultMap) {
    // check if the map is empty
    if (resultMap.isEmpty()) {
        return;
    }
    // create an array list for the list of vertices
    List<V> vertices = new ArrayList<>();
    // create an iterator for the map
    Iterator<String> iterator = resultMap.keySet().iterator();
    // loop through the map
    while (iterator.hasNext()) {
        // get the next key
        String key = iterator.next();
        // get the corresponding vertex
        V vertex = resultMap.get(key);
        // add the vertex to the list of vertices
        vertices.add(vertex);
    }
    // loop through the list of vertices
    for (int i = 0; i < vertices.size(); i++) {
        // get the current vertex
        V vertex = vertices.get(i);
        // loop through the rest of the list of vertices
        for (int j = i + 1; j < vertices.size(); j++) {
            // get the next vertex
            V nextVertex = vertices.get(j);
            // create a new edge
            E edge = new Edge(vertex, nextVertex);
            // add the edge to the graph
            target.addEdge(edge);
        }
    }
}

public void generateGraph(Graph<V, E> target, Map<String, V> resultMap) {
    // Get the number of vertices in each partition
    int numVertices1 = resultMap.get("partition1").size();
    int numVertices2 = resultMap.get("partition2").size();

    // Initialize the graph
    if (target.getVertices().isEmpty()) {
        for (int i = 0; i < numVertices1; i++) {
            target.addVertex(resultMap.get("partition1").get(i));
        }
        for (int j = 0; j < numVertices2; j++) {
            target.addVertex(resultMap.get("partition2").get(j));
        }
    }

    // Add edges between the partitions
    for (int i = 0; i < numVertices1; i++) {
        for (int j = 0; j < numVertices2; j++) {
            target.addEdge(resultMap.get("partition1").get(i), resultMap.get("partition2").get(j));
        }
    }
}

public void generateGraph(Graph<V, E> target, Map<String, V> resultMap) {
    for (String key : resultMap.keySet()) {
        V node = resultMap.get(key);
        if (node.getNeighbors().size() > 0) {
            target.addNode(node);
            for (E neighbor : node.getNeighbors()) {
                V neighborNode = resultMap.get(neighbor.getNodeId());
                if (neighborNode.getNeighbors().size() > 0) {
                    target.addEdge(neighborNode, node);
                }
            }
        }
    }
}

