                }
                result.properties.put(property, filteredItems);
            } else if (propertyValue instanceof Map) {
                result.properties.put(property, filterItem((Map<String, Object>) propertyValue));
            }
        }
        return result;
    } catch (Exception ex) {
        throw new RuntimeException("Error while diffening mappings structure: " + ex.getMessage(), ex);
    }
}

private Map<String, Object> filterItem(Map<String, Object> item) {
    Map<String, Object> filteredItem = new HashMap<>();
    for (String key : item.keySet()) {
        Object value = item.get(key);
        if (value == null) {
            continue; // ignore null values
        } else if (value instanceof Map) {
            filteredItem.put(key, filterItem((Map<String, Object>) value)); // recursive call
        } else {
            filteredItem.put(key, value);
        }
    }
    return filteredItem;
}

