private static long readLong(ClassReader classReader, int offset) throws IOException {
    long value = 0L;
    for (int i = 0; i < 8; i++) {
        value |= (long) (classReader.readByte(offset + i) & 0xFF) << (8 * i);
    }
    return value;
}

public long readLong(int offset) {
    // Ensure that the value is within the bounds of the ClassReader buffer
    if (offset < 0 || offset + 8 > buffer.length) {
        throw new IndexOutOfBoundsException("Invalid offset: " + offset);
    }

    // Read the long value from the buffer
    long value = (long) ((buffer[offset++] & 0xFF) |
            ((buffer[offset++] & 0xFF) << 8) |
            ((buffer[offset++] & 0xFF) << 16) |
            ((buffer[offset++] & 0xFF) << 24) |
            ((long) (buffer[offset++] & 0xFF) << 32) |
            ((long) (buffer[offset++] & 0xFF) << 40) |
            ((long) (buffer[offset++] & 0xFF) << 48) |
            ((long) (buffer[offset] & 0xFF) << 56));

    // Return the read value
    return value;
}

