protected List<TimeRange> buildTimeRanges(long start, long end) {
    List<TimeRange> timeRanges = new ArrayList<>();

    // Calculate the length of the time range
    long duration = end - start;

    // If the duration is less than or equal to the fetch data duration,
    // we can return a single time range with the entire duration
    if (duration <= FETCH_DATA_DURATION) {
        timeRanges.add(new TimeRange(start, duration));
        return timeRanges;
    }

    // Otherwise, we need to split the time range into multiple time ranges
    // with a duration of FETCH_DATA_DURATION
    long remainingDuration = duration;
    long startTime = start;
    while (remainingDuration > 0) {
        long endTime = startTime + FETCH_DATA_DURATION;
        if (endTime >= end) {
            endTime = end;
        }
        timeRanges.add(new TimeRange(startTime, endTime - startTime));
        startTime = endTime;
        remainingDuration = duration - (endTime - start);
    }

    return timeRanges;
}

protected List<TimeRange> buildTimeRanges(long start, long end) {
    List<TimeRange> timeRanges = new ArrayList<>();
    long duration = FETCH_DATA_DURATION;
    long diff = end - start;
    if (diff <= duration) {
        timeRanges.add(new TimeRange(start, end));
        return timeRanges;
    }
    long mid = start + (diff / 2);
    long start1 = start, end1 = mid, start2 = mid, end2 = end;
    // Recursively split the ranges
    timeRanges.addAll(buildTimeRanges(start1, end1));
    timeRanges.addAll(buildTimeRanges(start2, end2));
    return timeRanges;
}

private List<TimeRange> buildTimeRanges(long start, long end) {
    List<TimeRange> timeRanges = new ArrayList<>();
    long currentStart = start;
    while (currentStart + FETCH_DATA_DURATION <= end) {
        timeRanges.add(new TimeRange(currentStart, currentStart + FETCH_DATA_DURATION));
        currentStart += FETCH_DATA_DURATION;
    }
    if (currentStart < end) {
        timeRanges.add(new TimeRange(currentStart, end));
    }
    return timeRanges;
}

private static List<TimeRange> buildTimeRanges(long start, long end) {
    List<TimeRange> timeRanges = new ArrayList<>();
    long range = end - start;
    while (range >= FETCH_DATA_DURATION) {
        long currentStart = start;
        start = Math.min(end, currentStart + FETCH_DATA_DURATION);
        timeRanges.add(new TimeRange(currentStart, start));
        range = end - start;
    }
    // Add the remaining time range
    if (range > 0) {
        timeRanges.add(new TimeRange(start, end));
    }
    return timeRanges;
}

protected List<TimeRange> buildTimeRanges(long start,long end){
    List<TimeRange> timeRanges = new ArrayList<>();
    while (start < end) {
        long startTime = Math.min(start, start % FETCH_DATA_DURATION);
        long endTime = Math.min(end, startTime + FETCH_DATA_DURATION);
        timeRanges.add(new TimeRange(startTime, endTime));
        start += FETCH_DATA_DURATION;
    }
    return timeRanges;
}

