public static String reverse(String str) {
    if (str == null) {
        return null;
    }

    final int length = str.length();
    if (length == 0) {
        return "";
    }

    final StringBuilder sb = new StringBuilder(length);
    for (int i = length - 1; i >= 0; i--) {
