            throw new IllegalArgumentException("Invalid byte array offset: " + byteOffset);
        }
        if (byteLength < 0 || byteOffset + byteLength > byteArrayValue.length) {
            throw new IllegalArgumentException("Invalid byte array length: " + byteLength);
        }
        // Check if we need to resize the buffer.
