    if(this.treePrev != null && this.treeNext != null){
        // Remove edge from list of previous tree edge
        if(this.treePrev != null){
            this.treePrev.treeNext = this.treeNext;
        }
        // Remove edge from list of next tree edge
        if(this.treeNext != null){
            this.treeNext.treePrev = this.treePrev;
        }
        // Set both edges to null
        this.treePrev = null;
        this.treeNext = null;
    }
}

public void removeFromTreeEdgeList() {
    // get the previous and next edges
    TreeEdge<E> prevEdge = this.getPrevEdge();
    TreeEdge<E> nextEdge = this.getNextEdge();

    // update the previous and next edges
    if (prevEdge != null) {
        prevEdge.setNextEdge(nextEdge);
    }
    if (nextEdge != null) {
        nextEdge.setPrevEdge(prevEdge);
    }

    // set both edges to null
    this.setPrevEdge(null);
    this.setNextEdge(null);
}

