}

public void removeFromTreeEdgeList() {
    // Check if the edge is already removed from the list
    if (treeEdge == null) {
        return;
    }

    // Remove the edge from the list of root edges
    if (treeEdge.left == this) {
        treeEdge.left = treeEdge.left.next;
    }
    if (treeEdge.right == this) {
        treeEdge.right = treeEdge.right.next;
    }

    // Update the next and previous pointers of the edges
    // that come after this edge in the list
    if (next != null) {
        next.prev = prev;
    }
    if (prev != null) {
        prev.next = next;
    }

    // Set the edge to null to indicate that it is removed from the list
    treeEdge = null;
}

