public static String findAndSubst(String key, Properties props) {
    if (props == null || key == null) {
        return null;
    }

    String value = props.getProperty(key);
    if (value == null) {
        return null;
    }

    return substVars(value, props);
}

private static String substVars(String str, Properties props) {
    if (str == null || props == null) {
        return null;
    }

    for (String var : props.stringPropertyNames()) {
        str = str.replaceAll("\\$\\{" + var + "\\}", props.getProperty(var));
    }

    return str;
}

