    }
    return str.endsWith(suffix);
}

public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    List<PathSegmentImpl> pathSegments = new ArrayList<>();
    String path = u.getPath();

    // Skip leading slash if absolute path
    if (path.charAt(0) == '/') {
        path = path.substring(1);
    }

    // Split path into segments
    String[] segments = path.split("/");

    // Decode segments if necessary
    if (decode) {
        for (int i = 0; i < segments.length; i++) {
            segments[i] = URLDecoder.decode(segments[i], StandardCharsets.UTF_8);
        }
    }

    // Convert to PathSegmentImpl instances
    for (String segment : segments) {
        pathSegments.add(new PathSegmentImpl(segment));
    }

    return pathSegments;
}

public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    List<PathSegmentImpl> pathSegments = new ArrayList<>();
    // Check if the URI is null
    if (u == null) {
        return pathSegments;
    }

    try {
        // Get the path component of the URI
        String path = u.getPath();
        // Check if the path is null or empty
        if (path == null || path.isEmpty()) {
            return pathSegments;
        }

        // Split the path component into path segments
        String[] segments = path.split("/");
        // Iterate over the path segments and add them to the list
        for (String segment : segments) {
            // Check if the segment is null or empty
            if (segment != null && !segment.isEmpty()) {
                if (decode) {
                    // Decode the segment and add it to the list
                    pathSegments.add(new PathSegmentImpl(URLDecoder.decode(segment, "UTF-8")));
                } else {
                    // Add the segment as is to the list
                    pathSegments.add(new PathSegmentImpl(segment));
                }
            }
        }

        return pathSegments;
    } catch (Exception e) {
        // log the exception and return an empty list
        System.err.println("Error decoding URI path: " + e.getMessage());
        return pathSegments;
    }
}

public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    List<PathSegmentImpl> pathSegments = new ArrayList<>();
    if (u.isAbsolute()) {
        String[] segments = u.getPath().split("/");
        for (String segment : segments) {
            if (decode) {
                segment = URLDecoder.decode(segment, "UTF-8");
            }
            pathSegments.add(new PathSegmentImpl(segment));
        }
    } else {
        String[] segments = u.getPath().split("/");
        for (int i = 1; i < segments.length; i++) {
            if (decode) {
                segment = URLDecoder.decode(segments[i], "UTF-8");
            }
            pathSegments.add(new PathSegmentImpl(segment));
        }
    }
    return pathSegments;
}

public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    List<PathSegmentImpl> pathSegments = new ArrayList<>();

    // Check if the path component is empty
    if (u.getPath() == null || u.getPath().isEmpty()) {
        return pathSegments;
    }

    // Decode the path component if requested
    if (decode) {
        try {
            u = new URI(u.getScheme(), u.getHost(), u.getPath(), u.getQuery(), u.getFragment());
        } catch (URISyntaxException e) {
            // Ignore, just use the original URI
        }
    }

    // Split the path component into segments
    String[] segments = u.getPath().split("/");

    // Add each segment to the list of path segments
    for (String segment : segments) {
        if (segment == null || segment.isEmpty()) {
            continue;
        }
        PathSegmentImpl pathSegment = new PathSegmentImpl(segment);
        pathSegments.add(pathSegment);
    }

    return pathSegments;
}

public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    List<PathSegmentImpl> pathSegments = new ArrayList<>();
    String[] pathComponents = u.getPath().split("/");
    for (String pathComponent : pathComponents) {
        try {
            String pathSegment = URLDecoder.decode(pathComponent, "UTF-8");
            if (decode) {
                pathSegments.add(new PathSegmentImpl(pathSegment));
            } else {
                pathSegments.add(new PathSegmentImpl(pathComponent));
            }
        } catch (UnsupportedEncodingException e) {
            throw new RuntimeException(e);
        }
    }
    return pathSegments;
}

