	public static Converter lookup(final Class<?> clazz) {
		// Step 1: Check if the class is convertible
		if (!clazz.isConvertible()) {
			return null;
		}

		// Step 2: Look up the registered converter
		for (Converter converter : ConverterRegistry.getConverters()) {
			if (converter.canConvert(clazz)) {
				return converter;
			}
		}

		// Step 3: If no converter is found, return null
		return null;
	}
}

public long readRawVarint64() throws IOException {

    // Initialize the result and the current byte value
    long result = 0;
    int currentByte = 0;

    // Loop until you have read 64 bits or hit the end of the stream
    while (currentByte != -1 && result < 0x8000000000000000L) {

        // Shift the previous bits left by 7 and then set the lowest bit to the result of reading a single byte
        result = (result << 7) | (currentByte & 0x7f);

        // Set the highest bit to 0 (indicating that another byte should be read)
        currentByte = inputStream.read();
    }

    if (currentByte == -1 && result == 0) {
        throw new EOFException();
    }

    // Return the complete Varint
    return result;
}

public long readRawVarint64() throws IOException {
  int shift = 0;
  long result = 0;
  while (shift < 64) {
    final byte b = in.readRawByte();
    result |= (long) (b & 0x7F) << shift;
    if ((b & 0x80) == 0) {
      return result;
    }
    shift += 7;
  }
  throw new IllegalStateException("VarInt too large");
}

