}

public long readRawVarint64() throws IOException {
    byte tmp = in.readByte();
    if (tmp >= 0) {
        return tmp;
    }
    int result = tmp & 0x7f;
    if ((tmp = in.readByte()) >= 0) {
        return result | (tmp << 7);
    }
    result |= (tmp & 0x7f) << 7;
    if ((tmp = in.readByte()) >= 0) {
        return result | (tmp << 14);
    }
    result |= (tmp & 0x7f) << 14;
    if ((tmp = in.readByte()) >= 0) {
        return result | (tmp << 21);
    }
    result |= (tmp & 0x7f) << 21;
    return result;
}

