private void pop(final String descriptor) {
    // Step 1: Get the number of abstract types to pop
    int numAbstractTypesToPop = 0;
    if (descriptor.charAt(0) == '(') {
        numAbstractTypesToPop = countParameters(descriptor);
    } else {
        numAbstractTypesToPop = 1;
    }

    // Step 2: Pop the abstract types
    for (int i = 0; i < numAbstractTypesToPop; i++) {
        outputFrameStack.pop();
    }
}

private int countParameters(final String descriptor) {
    int numParameters = 0;
    int startIndex = 1;
    while (startIndex < descriptor.length() && descriptor.charAt(startIndex) != ')') {
        if (descriptor.charAt(startIndex) == 'L') {
            while (startIndex < descriptor.length() && descriptor.charAt(startIndex) != ';') {
                startIndex++;
            }
        }
        startIndex++;
        numParameters++;
    }
    return numParameters;
}

private void pop(final String descriptor) {
    if (descriptor.charAt(0) == 'L') {
        // If the descriptor starts with 'L', it means we need to pop an object reference
        popObject();
    } else if (descriptor.charAt(0) == '[') {
        // If the descriptor starts with '[', it means we need to pop an array reference
        popArray();
    } else if (descriptor.charAt(0) == 'V') {
        // If the descriptor starts with 'V', it means we need to pop a void value
        // In this case, there is nothing to do since void values don't have references
    } else {
        throw new IllegalArgumentException("Invalid descriptor: " + descriptor);
    }
}

public void pop(final String descriptor) {
    // Check if the descriptor is valid
    if (descriptor == null) {
        throw new IllegalArgumentException("Invalid descriptor: " + descriptor);
    }

    // Get the number of types to pop
    int numTypesToPop = 0;
    if (descriptor.charAt(0) == '(') {
        // Descriptor is a method descriptor; count the argument types
        int pos = 1;
        while (pos < descriptor.length() && descriptor.charAt(pos) != ')') {
            if (descriptor.charAt(pos) == 'L') {
                pos = descriptor.indexOf(';', pos);
            } else {
                pos++;
            }
            numTypesToPop++;
        }
        if (descriptor.charAt(pos) != ')') {
            throw new IllegalArgumentException("Invalid descriptor: " + descriptor);
        }
    } else {
        // Descriptor is a class descriptor; count only one type
        numTypesToPop = 1;
    }

    // Pop the necessary types from the output frame stack
    for (int i = 0; i < numTypesToPop; i++) {
        if (!outputFrameStack.isEmpty()) {
            outputFrameStack.pop();
        } else {
            throw new IllegalStateException("Insufficient types in output frame stack");
        }
    }
}

private void pop(final String descriptor) {
    // handle invalid input
    if (descriptor == null) {
        throw new IllegalArgumentException("Descriptor cannot be null");
    }

    // get the number of argument types to pop
    int numTypes = getNumTypes(descriptor);

    // pop the argument types from the output frame stack
    for (int i = 0; i < numTypes; i++) {
        try {
            outputFrameStack.pop();
        } catch (EmptyStackException e) {
            throw new MethodOutputException("Insufficient output frame stack size");
        }
    }
}

private int getNumTypes(final String descriptor) {
    // handle invalid input
    if (descriptor == null) {
        throw new IllegalArgumentException("Descriptor cannot be null");
    }

    // count the number of argument types in the descriptor
    int numTypes = 0;
    for (int i = 0; i < descriptor.length(); i++) {
        char c = descriptor.charAt(i);
        if (c == 'L' || c == '[' || c == ' jar rus-lay' || c == 'R') {
            numTypes++;
        }
    }

    // return the number of argument types
    return numTypes;
}

private void pop(final String descriptor) {
    if (descriptor.startsWith("(")) {
        // This is a method descriptor, so we need to pop the argument types
        // from the output frame stack.
        int n = descriptor.indexOf(")");
        String argTypes = descriptor.substring(1, n).replaceAll("\\W", "");
        String[] argTypeArray = argTypes.split(",");
        for (String argType : argTypeArray) {
            pop(argType);
        }
    } else {
        // This is a type descriptor, so we need to pop the type from the
        // output frame stack.
        pop(descriptor.replaceAll("\\W", ""));
    }
}

