    if (off < 0 || len < 0 || off + len > b.length) {
        throw new IndexOutOfBoundsException("Invalid off or len");
    }
    if (len == 0) {
        return;
    }
    synchronized (this) {
        ensureOpen();
        if (off < 0 || len < 0 || off + len > b.length) {
