public void addToIndex(V sourceVertex, V targetVertex, E e){
    // Step 1: check if the source and target vertices are valid
    if(sourceVertex == null || targetVertex == null){
        throw new IllegalArgumentException("Source and target vertices cannot be null");
    }

    // Step 2: add the edge to the index
    index.put(sourceVertex, targetVertex, e);

    // Step 3: add the edge to the target vertex's adjacency list
    targetVertex.adjacentVertices.add(e);
}

protected void addToIndex(V sourceVertex, V targetVertex, E e) {
    // step 1: check if the edge already exists in the index
    if (index.containsKey(sourceVertex) && index.get(sourceVertex).contains(targetVertex)) {
        throw new IllegalArgumentException("Edge already exists in the index.");
    }

    // step 2: add the edge to the index
    if (!index.containsKey(sourceVertex)) {
        index.put(sourceVertex, new HashSet<>());
    }
    index.get(sourceVertex).add(targetVertex);

    // step 3: add the edge to the index (symmetrically)
    if (!index.containsKey(targetVertex)) {
        index.put(targetVertex, new HashSet<>());
    }
    index.get(targetVertex).add(sourceVertex);
}

protected void addToIndex(V sourceVertex, V targetVertex, E e) {
    // Step 1: Check if the edge already exists in the index
    if (index.containsKey(sourceVertex) && index.get(sourceVertex).containsKey(targetVertex)) {
        // Edge already exists, do nothing
        return;
    }
    // Step 2: Add the edge to the index
    if (index.get(sourceVertex) == null) {
        index.put(sourceVertex, new HashMap<>());
    }
    index.get(sourceVertex).put(targetVertex, e);
}

protected void addToIndex(V sourceVertex, V targetVertex, E e) {
    if (sourceVertex == null || targetVertex == null || e == null) {
        throw new IllegalArgumentException("Source vertex, target vertex, and edge must be non-null");
    }

    if (sourceVertex == targetVertex) {
        throw new IllegalArgumentException("Source vertex and target vertex must be different");
    }

    // Add the edge to the index
    index.put(sourceVertex, targetVertex, e);
}

protected void addToIndex(V sourceVertex, V targetVertex, E e) {
    // Step 1: Check for null inputs
    if (sourceVertex == null || targetVertex == null || e == null) {
        throw new IllegalArgumentException("Inputs cannot be null");
    }

    // Step 2: Check if the edge already exists
    if (getEdge(sourceVertex, targetVertex) != null) {
        throw new IllegalStateException("Edge already exists");
    }

    // Step 3: Add the edge to the index
    index.add(sourceVertex, targetVertex, e);
}

public static File[] classPath() {
