  String[] classPathStrings = System.getProperty("java.class.path").split(";");

  // Initialize an empty array to hold the File objects
  File[] classPath = new File[classPathStrings.length];

  // Loop through the string array and create a File object for each element
  for (int i = 0; i < classPathStrings.length; i++) {
    classPath[i] = new File(classPathStrings[i]);
  }

  // Return the array of File objects
  return classPath;
}

