public static int writeTo(final DataOutput out, LinkedBuffer node) throws IOException {
    // Step 1: Check if the node is null
    if (node == null) {
        throw new IllegalArgumentException("LinkedBuffer node cannot be null");
    }

    // Step 2: Write the node's data to the output stream
    out.writeInt(node.getData().length);
    for (int i = 0; i < node.getData().length; i++) {
        out.writeByte(node.getData()[i]);
    }

    // Step 3: Write the node's next node to the output stream
    out.writeInt(node.getNext().getData().length);
    for (int i = 0; i < node.getNext().getData().length; i++) {
        out.writeByte(node.getNext().getData()[i]);
    }

    // Step 4: Write the node's previous node to the output stream
    out.writeInt(node.getPrevious().getData().length);
