protected Character convertToType(final Class<?> type, final Object value) throws Exception {
    if (type.equals(Character.class) || type.equals(char.class)) {
        return Character.valueOf((char) value);
    } else if (type.isPrimitive()) {
        throw new IllegalArgumentException("Cannot convert string to primitive type");
    } else if (type.isEnum()) {
        // Handle enum conversion
        return Enum.valueOf((Class<? extends Enum>) type, (String) value);
    } else {
        // Handle custom type conversion
        return type.getDeclaredMethod("valueOf", String.class).invoke(null, value);
    }
}

