public static String trimTrailingWhitespace(String str) {
    int length = str.length();
    while (length > 0 && Character.isWhitespace(str.charAt(length - 1))) {
        length--;
    }
    return str.substring(0, length);
}

public static String trimTrailingWhitespace(String str) {
    // Check if the input String is null or empty
    if (str == null || str.isEmpty()) {
        return str;
    }

    // Get the length of the input String
    int len = str.length();

    // Get the index of the last character that is not whitespace
    int lastNonWhitespaceIndex = len - 1;
    for (int i = len - 1; i >= 0; i--) {
        if (!Character.isWhitespace(str.charAt(i))) {
            lastNonWhitespaceIndex = i;
            break;
        }
    }

    // If the last character is not whitespace, return the input String
    // Otherwise, return a new String that is a substring of the input String
    // starting from the first character and ending at the last non-whitespace character
    if (lastNonWhitespaceIndex == len - 1) {
        return str;
    }
    return str.substring(0, lastNonWhitespaceIndex + 1);
}

public static String trimTrailingWhitespace(String str) {
    if (str == null) {
        return null;
    }
    int length = str.length();
    int start = 0;
    while (start < length && Character.isWhitespace(str.charAt(start))) {
        start++;
    }
    if (start == 0) {
        return str;
    }
    if (start == length) {
        return "";
    }
    return str.substring(start, length);
}

public static String trimTrailingWhitespace(String str) {

  // Check if str is null or empty
  if (str == null || str.isEmpty()) {
    return str;
  }

  // Find the last index of a non-whitespace character
  int lastNonWhitespaceIndex = str.length() - 1;
  while (lastNonWhitespaceIndex >= 0 && Character.isWhitespace(str.charAt(lastNonWhitespaceIndex))) {
    lastNonWhitespaceIndex--;
  }

  // Return a substring of str starting from the index of the last non-whitespace character
  return str.substring(0, lastNonWhitespaceIndex + 1);
}

public static String trimTrailingWhitespace(String str) {
    if (str == null || str.isEmpty()) {
        return str;
    }

    int end = str.length() - 1;
    while (end >= 0 && Character.isWhitespace(str.charAt(end))) {
        end--;
    }

    return str.substring(0, end + 1);
}

