private static int digitValue(final char c){
    // Check that the character is a digit
    if(!Character.isDigit(c)){
        throw new IllegalArgumentException("Character is not a digit");
    }

    // Calculate the digit value
    int value = Character.digit(c, 36);

    // If the value is less than 0, it means that the character is not a valid digit in base 36
    if(value < 0){
        throw new IllegalArgumentException("Character is not a valid digit in base 36");
    }

    return value;
}

