        result = Arrays.copyOf(result, result.length + buffer.remaining());
        buffer.get(result, result.length - buffer.remaining(), buffer.remaining());
    }
    return result;
}

public byte[] toByteArray() {
    // Create a list to store the contents of the buffer(s)
    List<byte[]> bufferContents = new ArrayList<>();

    // Get the current buffer and append its contents to the list
    byte[] currentBuffer = getByteBuffer().array();
    bufferContents.add(currentBuffer);

    // Get the remaining buffers and append their contents to the list
    for (int i = 1; i < buffers.size(); i++) {
        currentBuffer = buffers.get(i).array();
        bufferContents.add(currentBuffer);
    }

    // Allocate an array to store the contents of all the buffers
    byte[] result = new byte[bufferContents.stream().mapToInt(b -> b.length).sum()];

    // Copy the contents of each buffer to the result array
    int offset = 0;
    for (byte[] buffer : bufferContents) {
        System.arraycopy(buffer, 0, result, offset, buffer.length);
        offset += buffer.length;
    }

    return result;
}

