public short readShort(final int offset) {
    // Throw an exception if the input is invalid
    if (offset < 0 || offset > this.length - 2) {
        throw new IllegalArgumentException("Offset out of bounds");
    }

    // Read the short value from the given offset
    int hiByte = this.data[offset] & 0xFF;
    int loByte = this.data[offset + 1] & 0xFF;
    return (short) (hiByte << 8 | loByte);
}

public short readShort(int offset) {
    if (offset < 0 || offset + 2 > code.length) {
        throw new IndexOutOfBoundsException("Invalid offset: " + offset + ". Code length: " + code.length);
    }

    short value = (short) ((code[offset] & 0xff) << 8);
    value |= code[offset + 1] & 0xff;
    return value;
}

