        throw new RuntimeException("Invalid offset");
    }
    return value;
}

public static Object copyArrayGrow1(Object array, Class<?> newArrayComponentType) {
    // Check for null input and invalid array type
    if (array == null) {
        if (newArrayComponentType == null) {
            throw new IllegalArgumentException("newArrayComponentType cannot be null if array is null");
        }
        array = Array.newInstance(newArrayComponentType, 1);
    } else if (!array.getClass().isArray()) {
        throw new IllegalArgumentException("array must be an array type");
    } else {
        int originalLength = Array.getLength(array);
        Object newArray = Array.newInstance(array.getClass().getComponentType(), originalLength + 1);
        System.arraycopy(array, 0, newArray, 0, originalLength);
        array = newArray;
    }
    return array;
}

