        array = (Object[]) Array.newInstance(newArrayComponentType, 1);
    } else {
        // If the input array is not null, create a new array of the same size as the original array
        array = Arrays.copyOf(array, array.length + 1);
    }

    // Add a new element to the end of the array
    array[array.length - 1] = null;

    return array;
}

