public int removeUnusedNodes() {
    int removedNodes = 0;

    // Create a list to store the active nodes
    List<CategoryNode> activeNodes = new ArrayList<>();

    // Iterate over all nodes in the category tree
    for (CategoryNode node : getAllNodes()) {
        // If the node is active, add it to the list of active nodes
        if (node.isActive()) {
            activeNodes.add(node);
        }
    }

    // Iterate over all nodes in the category tree
    for (CategoryNode node : getAllNodes()) {
        // If the node is not active and has no child nodes, remove it
        if (!node.isActive() && node.getChildNodes().isEmpty()) {
            removedNodes++;
            removeNode(node);
        }
    }

    return removedNodes;
}

protected List<CategoryNode> getAllNodes() {
    List<CategoryNode> allNodes = new ArrayList<>();

    for (CategoryNode node : categoryTree) {
        allNodes.add(node);

        // Recursively get all child nodes
        for (CategoryNode child : node.getChildNodes()) {
            allNodes.add(child);
        }
    }

    return allNodes;
}

protected void removeNode(CategoryNode node) {
    // If the node has a parent, remove it from the parent's child nodes
    if (node.getParent() != null) {
        node.getParent().getChildNodes().remove(node);
    }

    // If the node has child nodes, remove them as well
    for (CategoryNode child : node.getChildNodes()) {
        removeNode(child);
    }
}

int removeUnusedNodes() {
    // Iterate over the Category tree and remove any nodes with no connected children
    for (Category node : categoryTree.getNodes()) {
        if (node.getChildren().isEmpty()) {
            node.delete();
        }
    }
    // Return the number of nodes removed
    return categoryTree.getNodes().size() - categoryTree.getNodes().stream().filter(node -> !node.getChildren().isEmpty()).count();
}

public static int removeUnusedNodes(Category root) {
    if (root == null) {
        return 0;
    }

    int count = 0;

    for (Category child : root.getChildren()) {
        count += removeUnusedNodes(child);
    }

    if (root.isLeaf() && !root.isActive()) {
        root.setActive(false);
        count++;
    }

    return count;
}

protected int removeUnusedNodes() {
    int numRemovedNodes = 0;

    // Iterate over the category tree and remove any inactive nodes
    for (Category node : categoryTree) {
        if (!node.isActive()) {
            // Remove the inactive node from the tree and increment the number of removed nodes
            categoryTree.remove(node);
            numRemovedNodes++;
        }
    }

    return numRemovedNodes;
}

public int removeUnusedNodes() {
    // Get a list of all nodes in the tree
    List<Node> nodes = getAllNodes();

    // Initialize a variable to keep track of the number of nodes removed
    int numNodesRemoved = 0;

    // Iterate over all nodes in the tree
    for (Node node : nodes) {
        // Check if the node is inactive (i.e., has no direct children)
        if (!node.hasDirectChildren()) {
            // If the node is inactive, remove it from the tree
            removeNode(node);
            numNodesRemoved++;
        }
    }

    // Return the number of nodes removed
    return numNodesRemoved;
}

