public static String trimWhitespace(String str) {
    if (str == null) {
        return null;
    }
    int strLen = str.length();
    int start = 0;
    int end = strLen - 1;
    while (start < strLen) {
        if (Character.isWhitespace(str.charAt(start))) {
            break;
        } else {
            start++;
        }
    }
    while (end > start) {
        if (Character.isWhitespace(str.charAt(end))) {
            break;
        } else {
            end--;
        }
    }
    return str.substring(start, end + 1);
}

