    if (str == null || str.isEmpty()) {
        return str;
    }

    // Loop through the characters until you reach a non-whitespace character
    int start = 0;
    while (start < str.length() && Character.isWhitespace(str.charAt(start))) {
        start++;
    }

    // If the first character is a whitespace, return the remaining substring
    if (start > 0) {
        return str.substring(start);
    } else {
        return str;
    }
}

