private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    // Check if the start node is on the outer face of the component
    if (onOuterFace(start)) {
        // If the start node is on the outer face, start the traversal from it
        OuterFaceCirculator circulator = new OuterFaceCirculator(start, stop, dir);
        // Loop through the circulator and find the first node that satisfies the predicate
        for (Node node = circulator.next(); node != stop; node = circulator.next()) {
            if (predicate.test(node)) {
                return circulator;
            }
        }
        // If no nodes satisfy the predicate, return the circulator to the stop node
        return new OuterFaceCirculator(stop, stop, dir);
    } else {
        // If the start node is not on the outer face, perform a search from the front of the component
        Node componentFront = getComponentFront(start, dir);
        OuterFaceCirculator circulator = new OuterFaceCirculator(componentFront, stop, dir);
        // Loop through the circulator and find the first node that satisfies the predicate
        for (Node node = circulator.next(); node != stop; node = circulator.next()) {
            if (predicate.test(node)) {
                return circulator;
            }
        }
        // If no nodes satisfy the predicate, return the circulator to the stop node
        return new OuterFaceCirculator(stop, stop, dir);
    }
}

private Node selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    // Step 1: Find the starting node
    Node current = start;
    while (current != stop && !predicate.test(current)) {
        current = current.getNeighbor(dir);
    }

    // Step 2: Find the stopping node
    Node end = stop;
    while (end != start && !predicate.test(end)) {
        end = end.getNeighbor(dir);
    }

    // Step 3: Perform the traversal
    while (current != end) {
        current = current.getNeighbor(dir);
        if (predicate.test(current)) {
            return current;
        }
    }

    return end;
}

private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    // Create a circulator on the outer face of the component starting from the given start node
    OuterFaceCirculator circulator = new OuterFaceCirculator(start);

    // If the given start node satisfies the predicate, return it
    if (predicate.test(start)) {
        return new OuterFaceCirculator(start);
    }

    //
    // Do a breadth-first search on the graph starting from the outer face circulator
    // stop condition: reach the stop node or the circulator is exhausted
    // action: increment the direction of the circulator and check if the resulting node satisfies the predicate
    //
    while (circulator.hasNext()) {
        Node node = circulator.next();
        if (node == stop) {
            return circulator;
        }
        if (predicate.test(node)) {
            return new OuterFaceCirculator(node);
        }
        circulator.dir = dirOpposite(circulator.dir);
    }

    // No valid node found, return the circulator to the stop node
    return new OuterFaceCirculator(stop);
}

private List<Node> selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    List<Node> selection = new ArrayList<>();

    // Start from the given start node
    Node current = start;

    // Traverse the outer face of the component in the given direction
    while (current != stop) {
        // If the current node satisfies the given predicate, add it to the selection
        if (predicate.test(current)) {
            selection.add(current);
        }

        // Move to the next node in the given direction
        current = current.getNeighbor(dir);
    }

    // If the stop node was not reached yet, add it to the selection
    if (current == stop) {
        selection.add(stop);
    }

    return selection;
}

private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    // Start the circulator at the specified node
    OuterFaceCirculator circulator = new OuterFaceCirculator(start);

    // Advance the circulator while the nodes satisfy the predicate
    while (circulator.hasNext() && predicate.test(circulator.next())) {
        circulator.next();
    }

    // If the circulator reached the end of the outer face, wrap around to the start
    if (!circulator.hasNext()) {
        circulator.wrapAround();
    }

    // Advance the circulator again to get the desired node
    circulator.next();

    // Check if the node satisfies the predicate and return the circulator
    if (predicate.test(circulator.get())) {
        return circulator;
    }

    // If the node did not satisfy the predicate, return a circulator to the stop node
    return new OuterFaceCirculator(stop);
}

