public void add(LoggingEvent event) {
    synchronized (lock) {
        // Check if the buffer is full
        if (buffer.size() >= capacity) {
            // Drop the first event if the buffer is full
            LoggingEvent droppedEvent = buffer.poll();
            // Log the dropped event
            logger.log(Level.WARNING, "Dropped logging event: " + droppedEvent);
        }
        // Add the new event to the buffer
        buffer.add(event);
    }
}

