public ByteVector putByteArray(final byte[] byteArrayValue, final int byteOffset, final int byteLength) {
    // Check for null byteArrayValue
    if (byteArrayValue == null) {
        // Write nullbytes into this byte vector
        for (int i = 0; i < byteLength; i++) {
            this.putByte((byte) 0);
        }
        return this;
    }

    // Check for valid offset and length
    if (byteOffset < 0 || byteLength < 0 || byteOffset + byteLength > byteArrayValue.length) {
        throw new IndexOutOfBoundsException("Invalid offset and length");
    }

    // Copy byte array into this byte vector
    for (int i = 0; i < byteLength; i++) {
        this.putByte(byteArrayValue[byteOffset + i]);
    }
    return this;
}

