private static String putByteArray(byte[] byteArrayValue, int byteOffset, int byteLength) {
    if (byteArrayValue != null) {
        if (byteOffset < 0 || byteOffset >= byteArrayValue.length) {
            throw new IndexOutOfBoundsException("Invalid byte offset: " + byteOffset);
        }
        if (byteLength < 0 || (byteOffset + byteLength) > byteArrayValue.length) {
            throw new IndexOutOfBoundsException("Invalid byte length: " + byteLength);
        }
        if (byteLength == 0) {
            return "";
        }
        byte[] outputBytes = new byte[byteLength];
        System.arraycopy(byteArrayValue, byteOffset, outputBytes, 0, byteLength);
        return new String(outputBytes);
    } else {
        if (byteLength < 0) {
            throw new NegativeArraySizeException("Invalid byte length: " + byteLength);
        }
        byte[] outputBytes = new byte[byteLength];
        Arrays.fill(outputBytes, (byte) 0);
        return new String(outputBytes);
    }
}

