    byte[] byteArray = new byte[this.getLength()];

    // Iterate through each byte in the original byte array
    for (int i = 0; i < this.getLength(); i++) {
        // Copy the current byte to the new byte array
        byteArray[i] = this.get(i);
    }

    // Return the copied byte array
    return byteArray;
}

public byte[] toByteArray() {
    // Step 1: Validate input
    if (this == null) {
        throw new NullPointerException("Input stream cannot be null");
    }

    // Step 2: Calculate the size of the byte array
    int size = (int) this.getLength();

    if (size <= 0) {
        return new byte[0];
    }

    // Step 3: Copy the bytes to a new array
    byte[] byteArray = new byte[size];
    System.arraycopy(this.buffer, this.position, byteArray, 0, size);

    // Step 4: Return the byte array
    return byteArray;
}

