    }

    // Move all vertices from the bucket with the minimum label to the bucket with label 0
    bucketsByLabel.get(minLabel).forEach(vertex -> {
        bucketsByLabel.get(0).add(vertex);
        labels.set(vertex, 0);
    });

    // Clear the bucket with the minimum label
    bucketsByLabel.set(minLabel, new HashSet<>());

    // Update the labeling
    for (int i = 0; i < labels.size(); i++) {
