public boolean unlink(ListNodeImpl<E> node) {
    // Check if the node is not null
    if (node == null) {
        return false;
    }

    // Find the node's predecessor
    ListNodeImpl<E> predecessor = node.getPredecessor();

    // If the node is the head, set the new head
    if (predecessor == null) {
        head = node.getNext();
    } else {
        predecessor.setNext(node.getNext());
    }

    // If the node is the tail, set the new tail
    if (node.getNext() == null) {
        tail = node.getPredecessor();
    } else {
        node.getNext().setPredecessor(node.getPredecessor());
    }

    // Set the node's fields to null
    node.setNext(null);
    node.setPredecessor(null);

    size--;
    return true;
}

public void unlink(ListNodeImpl<E> node) {
    // check if the node is null
    if (node == null) {
        throw new NullPointerException("Node is null");
    }

    // check if the node is the head of the list
    if (node == head) {
        head = head.next;
    }

    // find the previous node to the node to be removed
    ListNodeImpl<E> previousNode = head;
    while (previousNode.next != node) {
        previousNode = previousNode.next;
    }

    // remove the node from the list
    previousNode.next = node.next;

    // return true if the node was removed successfully
    return true;
}

public boolean unlink(ListNodeImpl<E> node) {
    // Step 1: Check if the node is the first node in the list
    if (node.prev == null) {
        // Step 2: If the node is the first node, set the head to the next node
        head = node.next;
    } else {
        // Step 3: If the node is not the first node, set the previous node's next pointer to the next node
        node.prev.next = node.next;
    }
    // Step 4: Set the node's next pointer to null
    node.next = null;
    return true;
}

private boolean unlink(ListNodeImpl<E> node) {
    if (node == null) {
        return false;
    }

    ListNodeImpl<E> current = head;
    ListNodeImpl<E> previous = null;

    while (current != null) {
        if (current == node) {
            if (previous == null) {
                head = head.next;
            } else {
                previous.next = current.next;
            }
            current.next = null;
            size--;
            return true;
        }
        previous = current;
        current = current.next;
    }

    return false;
}

public List<SequenceRange> buildSequenceRanges(List<Long> profileIds, int maxNumRanges) {
    List<SequenceRange> sequenceRanges = new ArrayList<>();
    if (profileIds == null || profileIds.isEmpty()) {
        return sequenceRanges;
    }

    // Sort the profile IDs in ascending order
    List<Long> sortedProfileIds = new ArrayList<>(profileIds);
    Collections.sort(sortedProfileIds);

    // Create a range for each consecutive set of profile IDs
    for (int i = 0; i < sortedProfileIds.size() - 1; i++) {
        if (sortedProfileIds.get(i) + 1 == sortedProfileIds.get(i + 1)) {
            continue;
        }
        sequenceRanges.add(new SequenceRange(sortedProfileIds.get(i), sortedProfileIds.get(i + 1)));
        if (sequenceRanges.size() == maxNumRanges) {
            break;
        }
    }

    return sequenceRanges;
}

