    // Iterate over each profile in the current snapshot
    for (Profile profile : ProfileManager.getCurrentProfiles()) {
        // Get the sequence of the profile
        Sequence currentSequence = profile.getSequence();

        // If the sequence is not empty
        if (!currentSequence.isEmpty()) {
            // Get the first and last indices of the sequence
            int firstIndex = 0;
            int lastIndex = currentSequence.size() - 1;

            // Create a new SequenceRange object with the first and last indices
            SequenceRange sequenceRange = new SequenceRange(firstIndex, lastIndex);

            // Add the sequence range to the list
            sequenceRanges.add(sequenceRange);
        }
    }

    // Return the list of sequence ranges
    return sequenceRanges;
}

public List<SequenceRange> buildSequenceRanges() {
    List<SequenceRange> sequenceRanges = new ArrayList<>();

    // Step 1: Create a sequence range for each profile
    for (int i = 0; i < profiles.size(); i++) {
        SequenceRange sequenceRange = new SequenceRange();
        sequenceRange.setStart(profiles.get(i).getStart());
        sequenceRange.setEnd(profiles.get(i).getEnd());
        sequenceRanges.add(sequenceRange);
    }

    // Step 2: Sort the sequence ranges by start position
    sequenceRanges.sort((o1, o2) -> {
        return o1.getStart() - o2.getStart();
    });

    // Step 3: Combine overlapping sequence ranges
    for (int i = 0; i < sequenceRanges.size() - 1; i++) {
        SequenceRange current = sequenceRanges.get(i);
        SequenceRange next = sequenceRanges.get(i + 1);

        if (current.getEnd() >= next.getStart()) {
            current.setEnd(Math.max(current.getEnd(), next.getEnd()));
            sequenceRanges.remove(i + 1);
            i--;
        }
    }

    return sequenceRanges;
}

public List<SequenceRange> buildSequenceRanges() {
    // Step 1: Initialize an empty list to store the sequence ranges
    List<SequenceRange> sequenceRanges = new ArrayList<>();

    // Step 2: Iterate over the current profiles and build a list of unique sequence ranges
    for (Profile profile : currentProfiles) {
        // Step 3: Extract the sequence range from the profile
        SequenceRange sequenceRange = profile.getSequenceRange();

        // Step 4: Check if the sequence range already exists in the list
        if (!sequenceRanges.contains(sequenceRange)) {
            // Step 5: If it doesn't exist, add it to the list
            sequenceRanges.add(sequenceRange);
        }
    }

    // Step 6: Return the list of sequence ranges
    return sequenceRanges;
}

