private Pair<List<Integer>, Long> computeSuffixSum(List<Integer> bounds) {
    List<Integer> suffixSum = new ArrayList<>();
    long sum = 0;
    for (int i = bounds.size() - 1; i >= 0; i--) {
        sum += bounds.get(i);
        suffixSum.add(0, sum);
    }
    return new Pair<>(suffixSum, sum);
}

private Pair<List<Integer>, Long> computeSuffixSum(List<Integer> bounds) {
    if (bounds == null || bounds.isEmpty()) {
        return new Pair<>(Collections.emptyList(), 0L);
    }

    // Compute the suffix sum list
    List<Integer> suffixSum = new ArrayList<>(bounds.size());
    long sum = bounds.get(0);
    for (int i = 1; i < bounds.size(); i++) {
        sum += bounds.get(i);
        suffixSum.add((int) sum);
    }

    // Return the computed suffix sum list and the sum of all elements
    return new Pair<>(suffixSum, sum);
}

