    // Check if the input list is empty
    if (bounds.isEmpty()) {
        throw new IllegalArgumentException("Input list cannot be empty");
    }

    // Create an empty list to store the suffix sums
    List<Integer> suffixSum = new ArrayList<>();

    // Initialize the sum of all elements to 0
    long totalSum = 0;

    // Iterate over the list in reverse order
    for (int i = bounds.size() - 1; i >= 0; i--) {
        // Sum the current element with the previous element
        totalSum += bounds.get(i);

        // Add the sum to the suffix sum list
        suffixSum.add(0, totalSum);
    }

    // Return the computed suffix sum list and the total sum
    return new Pair<>(suffixSum, totalSum);
}

