void putAllWriteable(BeanMap map) {
  // Step 1: Check if the given BeanMap is null or empty
  if (map == null || map.isEmpty()) {
    return; // Return early if the given BeanMap is null or empty
  }
  // Step 2: Iterate over the writeable properties of the given BeanMap
  for (var entry : map.entrySet()) {
    // Step 3: Check if the current entry is a writable property
    if (entry.getKey().equalsIgnoreCase("readOnly") || entry.getKey().equalsIgnoreCase("writeOnly")) {
      continue; // Skip this entry if it is a read-only or write-only property
    }
    // Step 4: Put the value of the current entry into this BeanMap
    put(entry.getKey(), entry.getValue());
  }
}

