}

public void putAllWriteable(BeanMap map) {
    Map<String, Object> writeableProperties = map.getWriteablePropertyMap();
    for (Map.Entry<String, Object> entry : writeableProperties.entrySet()) {
        String key = entry.getKey();
        Object value = entry.getValue();
        try {
            // if the property is a writable getter, then set its value to this BeanMap
            Method getter = map.getBean().getClass().getMethod("get" + StringUtils.capitalize(key));
            if (getter != null && getter.getReturnType().equals(value.getClass())) {
                Method setter = map.getBean().getClass().getMethod("set" + StringUtils.capitalize(key), value.getClass());
                setter.invoke(map.getBean(), value);
            }
        } catch (NoSuchMethodException | IllegalAccessException | InvocationTargetException e) {
            // ignore and move on to the next property
        }
    }
}

