    List<Pair<List<Pair<Integer, Integer>>, E>> globalSeparatorList = new ArrayList<>();

    // Iterate over all edges in the graph
    for (E e : graph.edges()) {
        // Compute the list of minimal separators for the current edge
        List<Pair<List<Pair<Integer, Integer>>, E>> minimalSeparators = computeMinimalSeparators(e);

        // Concatenate the lists of minimal separators
