private List<Pair<List<Pair<Integer, Integer>>, E>> computeMinimalSeparators(E e) {
    List<Pair<List<Pair<Integer, Integer>>, E>> minimalSeparators = new ArrayList<>();

    // Get the neighborhood of the current edge
    Neighborhood<V, E> neighborhood = new Neighborhood<>(graph, e);

    // Iterate over all vertices in the neighborhood
    for (V v : neighborhood.getVertices()) {
        // Compute the list of minimal separators for the current vertex
        List<Pair<List<Pair<Integer, Integer>>, E>> minimalSeparatorsForVertex = computeMinimalSeparators(v);

        // Add the list of minimal separators to the global list of minimal separators
        minimalSeparators.addAll(minimalSeparatorsForVertex);
    }

    return minimalSeparators;
}

