void abbreviate(final int nameStart, final StringBuffer buf) {
    // Check for invalid input
    if (nameStart < 0 || nameStart >= buf.length()) {
        throw new IllegalArgumentException("Invalid nameStart parameter: " + nameStart);
    }
    if (buf == null) {
        throw new IllegalArgumentException("buf parameter cannot be null");
    }

    // Abbreviate the name
    int nameEnd = buf.indexOf(' ', nameStart);
    if (nameEnd == -1) {
        nameEnd = buf.length();
    }
    buf.replace(nameStart, nameEnd, getAbbreviation(buf, nameStart, nameEnd));
}

private String getAbbreviation(final StringBuffer buf, final int nameStart, final int nameEnd) {
    // Get the full name
    String name = buf.substring(nameStart, nameEnd);

    // Split the name into words
    String[] words = name.split(" ");

    // Filter out any non-word characters
    List<String> filteredWords = new ArrayList<>();
    for (String word : words) {
        if (word.matches("\\w+")) {
            filteredWords.add(word);
        }
    }

    // Join the first letter of each word and the last letter of the last word
    return filteredWords.stream()
            .map(word -> word.substring(0, 1))
            .collect(Collectors.joining()) + filteredWords.get(filteredWords.size() - 1).substring(filteredWords.get(filteredWords.size() - 1).length() - 1);
}

public void abbreviate(final int nameStart, final StringBuffer buf) {
    // Check for invalid input
    if (buf == null || nameStart < 0 || nameStart >= buf.length()) {
        throw new IllegalArgumentException("Invalid input buffer or name start");
    }

    // Abbreviate name
    int abbreviationLength = 0;
    String name = buf.substring(nameStart);
    for (int i = 0; i < name.length(); i++) {
        char c = name.charAt(i);
        if (Character.isUpperCase(c)) {
            abbreviationLength++;
        } else {
            // Skip any non-uppercase characters
            continue;
        }
        if (abbreviationLength == 1) {
            // First uppercase character encountered, append it to abbreviation
            buf.append(c);
        } else if (abbreviationLength == 2) {
            // Second uppercase character encountered, append dot and then character
            buf.append('.');
            buf.append(c);
        } else {
            // Third or subsequent uppercase character encountered, append dot and dot then character
            buf.append("...");
            buf.append(c);
        }
    }
}

