public static Type resolveBound(TypeVariable<?> typeVariable) {
    // Check for bounds
    Type[] bounds = typeVariable.getBounds();
    if (bounds.length > 0) {
        // Return the first bound if it's not a wildcard
        Type bound = bounds[0];
        if (!(bound instanceof WildcardType)) {
            return bound;
        }
    }
    // No bounds or wildcard bounds, return Unknown.class
    return Unknown.class;
}

public static Type resolveBound(TypeVariable<?> typeVariable) {
    Type resolvedBound = null;
    Class<?> declaringClass = typeVariable.getDeclaringClass();
    if (declaringClass != null) {
        resolvedBound = resolveBound(declaringClass.getGenericSuperclass(), typeVariable.getName());
        if (resolvedBound == null) {
            for (Type interfaceType : declaringClass.getGenericInterfaces()) {
                resolvedBound = resolveBound(interfaceType, typeVariable.getName());
                if (resolvedBound != null) {
                    break;
                }
            }
        }
    }
    if (resolvedBound == null) {
        resolvedBound = Unknown.class;
        System.err.println("Warning: unable to resolve bound for type variable " + typeVariable.getName() + ".");
    }
    return resolvedBound;
}

public static Type resolveBound(TypeVariable<?> typeVariable) {
    // Iterate over the bounds of the type variable and return the first one that is not equal to Object.class
    for (Type bound : typeVariable.getBounds()) {
        if (bound != Object.class) {
            return bound;
        }
    }
    // If no bounds are found, return Unknown.class
    return Unknown.class;
}

public static Type resolveBound(TypeVariable<?> typeVariable) {
    // Check if the type variable has a bound
    if (typeVariable.getBounds() != null && !typeVariable.getBounds().isEmpty()) {
        // Return the first bound
        return typeVariable.getBounds().iterator().next();
    } else {
        // Default to Unknown.class if no bound can be resolved
        return Unknown.class;
    }
}

private static <V, E> boolean isClique(Graph<V, E> graph, Set<V> vertices) {
    // Check if the given vertices are all contained in the graph
    if (!graph.containsAll(vertices)) {
        throw new IllegalArgumentException("The given vertices are not all contained in the graph");
    }

    // Check if the given vertices form a clique by checking if every edge is present in the graph
    for (V u : vertices) {
        int degreeU = graph.degreeOf(u);
        for (V v : vertices) {
            if (u != v) {
                // Skip self-loops
                if (u.equals(v)) {
                    continue;
                }
                // Check if the edge is present in the graph
                if (!graph.containsEdge(u, v)) {
                    return false;
                }
            }
        }
    }

    // If the code reaches this point, it means that all edges are present in the graph, so the induced subgraph is a clique
    return true;
}

