            }
        }
        upperBounds.add(upperBound);
    }
    return upperBounds;
}

public List<Integer> computeUpperBounds(List<K> keys) {
    List<Integer> upperBounds = new ArrayList<>(keys.size());
    for (K key : keys) {
        upperBounds.add(findLowerBound(key));
    }
    return upperBounds;
}

private int findLowerBound(K key) {
    int lowerBound = 0;
    for (int i = 0; i < keys.size(); i++) {
        if (key.compareTo(keys.get(i)) > 0) {
            lowerBound = i + 1;
        }
    }
    return lowerBound;
}

public List<Integer> computeUpperBounds(List<K> keys) {
    // Step 1: Initialize an empty hash table
    Map<K, Integer> upperBounds = new HashMap<>();

    // Step 2: Iterate over the input keys and compute the maximum value for each key
    for (K key : keys) {
        // If the current key is not in the hash table, add it with a value of 0
        if (!upperBounds.containsKey(key)) {
            upperBounds.put(key, 0);
        }

        // Get the current maximum value for the key
        int currentMax = upperBounds.get(key);

        // If the current key has a higher maximum value than 0, update the hash table
        if (currentMax > 0) {
            upperBounds.put(key, currentMax + 1);
        }
    }

    // Step 3: Return the computed key upper bounds
    return new ArrayList<>(upperBounds.values());
}

def computeUpperBounds(keys):
    """
    Finds a minimum lower bound for every key.
    :param keys: a list of keys.
    :return: the computed key upper bound.
    """
    # Initialize the upper bounds for each key as the key itself
    upper_bounds = {key: key for key in keys}

    # Iterate over the keys in descending order
    for key in sorted(keys, reverse=True):
        # If the key has not been processed, continue
        if upper_bounds[key] == key:
            continue

        # Find the closest key that has not been processed
        closest_key = None
        for j in range(len(keys)):
            if keys[j] < key and upper_bounds[keys[j]] != keys[j]:
                closest_key = keys[j]
                break

        # If no closest key found, set the key upper bound to itself
        if closest_key is None:
            upper_bounds[key] = key
        else:
            # Otherwise, set the key upper bound to the closest key
            upper_bounds[key] = closest_key

    return list(upper_bounds.values())

