public void append(LoggingEvent event) {
    // Ensure that the event is not null
    if (event == null) {
        throw new IllegalArgumentException("Logging event cannot be null");
    }

    // Get the current time
    Date date = new Date();

    // Format the time
    SimpleDateFormat formatter = new SimpleDateFormat("yyyy-MM-dd HH:mm:ss");
    String time = formatter.format(date);

    // Get the log message
    String message = event.getMessage();

    // Obtain the list of connected clients
    List<WebSocket> clients = event.getClients();

    // Iterate over the list of clients and send the log message to each client
    for (WebSocket client : clients) {
        try {
            // Send the log message to the client
            client.send(time + ": " + message);
        } catch (IOException e) {
            // Ignore the error if the client is already closed
            if (!client.isClosed()) {
                e.printStackTrace();
            }
        }
    }
}

protected void append(LoggingEvent event) {
    // If there are no connected clients, do nothing
    if (connectedClients.isEmpty()) {
        return;
    }

    // Use a buffered writer to send the log message to each connected client
    for (Socket socket : connectedClients) {
        BufferedWriter writer = new BufferedWriter(new OutputStreamWriter(socket.getOutputStream(), StandardCharsets.UTF_8));
        try {
            writer.write(event.getMessage());
            writer.newLine();
            writer.flush();
        } catch (IOException e) {
            // Ignore any exceptions and continue with the next client
            e.printStackTrace();
        }
    }
}

public void append(LoggingEvent event) {
    // Check if there are any connected clients
    if (this.clients.size() > 0) {
        // Get the message from the event
        String message = event.getMessage();
        // Iterate through each connected client
        for (Client client : this.clients) {
            try {
                // Send the message to the client
                client.send(message);
            } catch (IOException e) {
                // Log the error
                System.err.println("Error sending message to client:");
                e.printStackTrace();
            }
        }
    }
}

private void append(LoggingEvent event) {
    // Check if there are any connected clients before attempting to send the log event
    if (getConnectedClients().isEmpty()) {
        // Log a warning message indicating that there are no connected clients
        logger.warn("No connected clients detected. Log event will be discarded.");
        return;
    }

    // Create a new log event message
    String logMessage = createLogEventMessage(event);

    // Send the log event message to each connected client
    getConnectedClients().forEach(client -> client.sendLogEvent(logMessage));
}

