public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    // Create a list to store the thread snapshots
    List<ThreadSnapshot> threadSnapshots = new ArrayList<>();

    // Open the file for reading
    try (FileReader reader = new FileReader(file)) {
        // Create a buffered reader
        BufferedReader bufferedReader = new BufferedReader(reader);

        // Read the file line by line
        String line;
        while ((line = bufferedReader.readLine()) != null) {
            // Skip any empty lines or comments
            if (line.isEmpty() || line.startsWith("#")) {
                continue;
            }

            // Split the line into tokens
            String[] tokens = line.split(",");
            if (tokens.length != 4) {
                throw new IllegalStateException("Invalid line format: " + line);
            }

            // Get the time range for this thread snapshot
            ProfileAnalyzeTimeRange timeRange = timeRanges.stream()
                    .filter(range -> range.getId().equals(tokens[0]))
                    .findFirst()
                    .orElseThrow(() -> new IllegalStateException("No time range for " + tokens[0]));

            // Create a new thread snapshot and add it to the list
            threadSnapshots.add(new ThreadSnapshot(
                    Long.parseLong(tokens[0]), // id
                    Double.parseDouble(tokens[1]), // value
                    Double.parseDouble(tokens[2]), // stdDev
                    timeRange.getStartTime(), // startTime
                    timeRange.getEndTime() // endTime
            ));
        }
    }

    return threadSnapshots;
}

public static List<ThreadSnapshot> LoadThreadSnapshotsWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges)
{
    // Open the file
    using (var stream = new FileStream(file.FullName, FileMode.Open, FileAccess.Read))
    {
        // Read the contents of the file
        var streamReader = new StreamReader(stream);
        var fileContents = streamReader.ReadToEnd();

        // Create a new list to store the thread snapshots
        var threadSnapshots = new List<ThreadSnapshot>();

        // Loop through each time range
        foreach (var timeRange in timeRanges)
        {
            // Find the start and end index of the time range in the file contents
            var startIndex = fileContents.IndexOf(timeRange.StartTime);
            var endIndex = fileContents.IndexOf(timeRange.EndTime);

            // If the time range was not found, skip it
            if (startIndex == -1 || endIndex == -1)
                continue;

            // Extract the thread snapshot between the start and end indices
            var threadSnapshotText = fileContents.Substring(startIndex, endIndex - startIndex);

            // Parse the thread snapshot text into a ThreadSnapshot object
            var threadSnapshot = ThreadSnapshot.Parse(threadSnapshotText);

            // Add the thread snapshot to the list
            threadSnapshots.Add(threadSnapshot);
        }

        // Return the list of thread snapshots
        return threadSnapshots;
    }
}

